python3 - <<'EOF'
p='src/app/components/FormatModal.tsx'
s=open(p,encoding='utf8').read()
def rep(a,b):
    global s
    assert s.count(a)==1,a
    s=s.replace(a,b)
rep("""  parseKakaoBankWorkbook,
  groupKakaoRowsByMonth,""","""  parseKakaoBankWorkbook,
  groupKakaoRowsByMonth,
  mapCategory as kakaoDefaultCategory,""")
rep("import { loadHouseholdVendorRules, readHouseholdSuggestionBasis, suggestHouseholdCategory, type HouseholdVendorRule }",
    "import { loadHouseholdVendorRules, readHouseholdSuggestionBasis, resuggestHouseholdCategory, suggestHouseholdCategory, type HouseholdVendorRule }")
rep("""  const changeKakaoTransactionType = (month: string, rowId: string, transactionType: HouseholdEntry['transactionType']) => {
    const rules = householdImportRulesRef.current?.ownerUid === user?.uid ? householdImportRulesRef.current!.rules : [];
    replaceKakaoEntry(month, rowId, ({ subcategory, ...rest }) => {
      const nextOptions = householdCategoryOptions(householdCategoryViews[transactionType] || []);
      // 구분을 바꾸면 사용자가 고른 분류가 새 구분에도 있을 때만 유지하고, 아니면 기본 분류와 거래처 기억을 다시 적용한다.
      const keep = rest.categorySource === 'user' && nextOptions.includes(rest.category);
      return suggestHouseholdCategory(keep
        ? { ...rest, transactionType, ...(subcategory ? { subcategory } : {}) }
        : { ...rest, transactionType, category: nextOptions[0], categorySource: 'import-default' }, rules, householdCategoryViews);
    });
  };""","""  const kakaoImportRules = () => householdImportRulesRef.current?.ownerUid === user?.uid ? householdImportRulesRef.current!.rules : [];
  const changeKakaoTransactionType = (month: string, rowId: string, transactionType: HouseholdEntry['transactionType']) => {
    const rules = kakaoImportRules();
    replaceKakaoEntry(month, rowId, ({ subcategory, ...rest }) => {
      const nextOptions = householdCategoryOptions(householdCategoryViews[transactionType] || []);
      // 구분을 바꾸면 사용자가 고른 분류가 새 구분에도 있을 때만 유지하고, 아니면 첫 선택지가 아닌 파서 기본값과 거래처 기억을 다시 적용한다.
      const keep = rest.categorySource === 'user' && nextOptions.includes(rest.category);
      return suggestHouseholdCategory(keep
        ? { ...rest, transactionType, ...(subcategory ? { subcategory } : {}) }
        : { ...rest, transactionType, category: kakaoDefaultCategory(transactionType, rest.vendor), categorySource: 'import-default' }, rules, householdCategoryViews);
    });
  };
  // 거래처를 고치면 이전 거래처의 기억 분류·세부분류를 남기지 않는다. 식별자·원본 키·금액·날짜는 그대로다.
  const changeKakaoVendor = (month: string, rowId: string, vendor: string) => {
    const rules = kakaoImportRules();
    replaceKakaoEntry(month, rowId, entry => resuggestHouseholdCategory({ ...entry, vendor }, kakaoDefaultCategory(entry.transactionType, vendor), rules, householdCategoryViews));
  };""")
rep("onChange={(e) => updateKakaoRow(group.month, row.id, { vendor: e.target.value })}","onChange={(e) => changeKakaoVendor(group.month, row.id, e.target.value)}")
open(p,'w',encoding='utf8').write(s)
EOF
grep -rn "nextOptions\[0\]\|vendor: e.target.value" src/app/components/FormatModal.tsx test/*.mjs | head

cat >> test/householdSummary.test.mjs <<'EOF'

test("실제 SAYU 상세: 예전 단건(배열 없음·'[]')의 고친 분류·세부분류·메모를 보여 주고 사용자 본문은 그대로 안내한다", async () => {
  const { sayu, renderSayuDetail } = await import("./householdSayuView.helper.mjs");
  const legacy = {
    household_type: "지출", household_category: "식비", household_subcategory: "간식", household_categorySource: "user",
    household_vendor: "예전 가게", household_amount: "3000", household_payment: "현금", household_memo: "고친 메모\n둘째 줄",
    household_date: "2025-12-24", household_sayu: "예전 단건 본문",
  };
  for (const data of [legacy, { ...legacy, household_entries: "[]" }]) {
    const entries = sayu.parseHouseholdEntriesForSayu(data);
    assert.equal(entries.length, 1);
    assert.deepEqual([entries[0].category, entries[0].subcategory, entries[0].memo, entries[0].vendor, entries[0].amount], ["식비", "간식", "고친 메모\n둘째 줄", "예전 가게", "3000"]);
    const markup = renderToStaticMarkup(renderSayuDetail(data));
    assert.match(markup, /식비 · 간식 · 현금/);
    assert.match(markup, /메모: 고친 메모\n둘째 줄/);
    assert.match(markup, /3,000원/);
    // 예전 단건 본문은 덮어쓰지 않으므로 보존된 본문 안내를 표시한다. 원본 객체도 바뀌지 않는다.
    assert.match(markup, /기록 본문은 작성 당시 내용이며 자동으로 고치지 않습니다/);
    assert.equal(data.household_sayu, "예전 단건 본문");
  }
  // 거래도 단건 필드도 없는 '[]' 문서는 기존처럼 본문 보기를 쓴다.
  const empty = renderToStaticMarkup(renderSayuDetail({ household_entries: "[]", household_sayu: "빈 문서 본문" }));
  assert.match(empty, /<textarea[^>]*readonly=""[^>]*>빈 문서 본문<\/textarea>/);
});

test("실제 SAYU 상세: 손상된 배열은 단건 필드로 바꾸지 않고 기존 본문 보기를 유지한다", async () => {
  const { sayu, renderSayuDetail } = await import("./householdSayuView.helper.mjs");
  const data = { household_entries: "{broken", household_vendor: "단건 가게", household_amount: "1000", household_sayu: "손상 문서 본문" };
  assert.deepEqual(sayu.parseHouseholdEntriesForSayu(data), []);
  assert.equal(sayu.householdSayuIsUserText(data), false);
  const markup = renderToStaticMarkup(renderSayuDetail(data));
  assert.match(markup, /<textarea[^>]*>손상 문서 본문<\/textarea>/);
  assert.doesNotMatch(markup, /단건 가게/);
  assert.equal(data.household_entries, "{broken");
});

test("실제 SAYU 상세: 배열 거래는 기존처럼 자동 본문이면 안내하지 않고, 사용자 본문이면 안내하며 수입·지출 메모를 보여 준다", async () => {
  const { sayu, renderSayuDetail } = await import("./householdSayuView.helper.mjs");
  const { householdSayuText } = await import("../src/app/services/householdSaveService.ts");
  const list = [entry({ memo: "월세 메모" }), entry({ transactionType: "이체", memo: "내 계좌" })];
  const auto = { household_entries: JSON.stringify(list), household_sayu: householdSayuText(list), household_vendor: "단건 필드는 무시" };
  const autoMarkup = renderToStaticMarkup(renderSayuDetail(auto));
  assert.doesNotMatch(autoMarkup, /자동으로 고치지 않습니다/);
  assert.match(autoMarkup, /메모: 월세 메모/);
  assert.doesNotMatch(autoMarkup, /단건 필드는 무시/);
  assert.equal(sayu.parseHouseholdEntriesForSayu(auto).length, 2);
  assert.match(renderToStaticMarkup(renderSayuDetail({ ...auto, household_sayu: "사용자 본문" })), /자동으로 고치지 않습니다/);
});
EOF
